import unittest
from unittest.mock import Mock, call


def run(pipe):
    pipe.add("read")
    pipe.add("parse")


class TestPipeline(unittest.TestCase):
    def test_order(self):
        pipe = Mock()
        run(pipe)
        pipe.add.assert_has_calls([call("read"), call("parse")])


